const putCheckpoint = `-- name: PutCheckpoint :exec
INSERT INTO checkpoints (
    stack_id, update_id, lease_digest, schema_version, sequence,
    digest, invalid, features_json, deployment, saved_at_ms
) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (stack_id, update_id) DO UPDATE SET
    lease_digest = excluded.lease_digest,
    schema_version = excluded.schema_version,
    sequence = excluded.sequence,
    digest = excluded.digest,
    invalid = excluded.invalid,
    features_json = excluded.features_json,
    deployment = excluded.deployment,
    saved_at_ms = excluded.saved_at_ms
`

type PutCheckpointParams struct {
	StackID       string
	UpdateID      string
	LeaseDigest   []byte
	SchemaVersion int64
	Sequence      int64
	Digest        []byte
	Invalid       bool
	FeaturesJson  string
	Deployment    []byte
	SavedAtMs     int64
}

func (q *Queries) PutCheckpoint(ctx context.Context, arg PutCheckpointParams) error {
	_, err := q.db.ExecContext(ctx, putCheckpoint,
		arg.StackID,
		arg.UpdateID,
		arg.LeaseDigest,
		arg.SchemaVersion,
		arg.Sequence,
		arg.Digest,
		arg.Invalid,
		arg.FeaturesJson,
		arg.Deployment,
		arg.SavedAtMs,
	)
	return err
}

