const saveUpdate = `-- name: SaveUpdate :execrows
UPDATE updates
SET status = ?1, version = ?2, revision = ?3,
    lease_digest = ?4, lease_expires_at_ms = ?5,
    started_at_ms = ?6, ended_at_ms = ?7
WHERE stack_id = ?8 AND id = ?9
  AND revision = ?10
`

type SaveUpdateParams struct {
	Status           string
	Version          int64
	Revision         int64
	LeaseDigest      []byte
	LeaseExpiresAtMs int64
	StartedAtMs      int64
	EndedAtMs        int64
	StackID          string
	ID               string
	ExpectedRevision int64
}

// A compare-and-swap: it changes nothing unless the stored revision is the
// one the caller read.
func (q *Queries) SaveUpdate(ctx context.Context, arg SaveUpdateParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, saveUpdate,
		arg.Status,
		arg.Version,
		arg.Revision,
		arg.LeaseDigest,
		arg.LeaseExpiresAtMs,
		arg.StartedAtMs,
		arg.EndedAtMs,
		arg.StackID,
		arg.ID,
		arg.ExpectedRevision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const saveWorkspace = `-- name: SaveWorkspace :execrows
UPDATE workspaces
SET revision = ?1, lock_id = ?2, lock_holder = ?3,
    lock_reason = ?4, locked_at_ms = ?5, updated_at_ms = ?6
WHERE id = ?7 AND revision = ?8
`

